public class MyNotionDataProvider : INotionDataProvider
{
    private readonly List<PageRecord> _pages = [];

    public Task<INotionPage> GetPageAsync(string pageId)
    {
        var page = _pages.First(p => p.Id.ToString() == pageId);
        return Task.FromResult<INotionPage>(page);
    }

    public Task<IEnumerable<INotionPage>> GetChildPagesAsync(string? parentId)
    {
        var pages = _pages.Where(p => p.ParentId?.ToString() == parentId);
        return Task.FromResult(pages.Cast<INotionPage>());
    }

